export default function StatCard({ icon, label, value, sub, color = 'blue', glow = false }: any) {
  // Map standard colors to tailwind classes if needed, or use custom inline for the text color if dynamic.
  // For safety, we will just use the passed color directly in style for the value, but tailwind for the rest.
  return (
    <div className={`flex-1 min-w-[140px] bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-5 transition-all duration-300 hover:shadow-lg dark:hover:shadow-slate-800/50 ${glow ? 'shadow-md dark:shadow-slate-800' : ''}`}>
      <div className="text-2xl mb-2">{icon}</div>
      <div className="font-mono text-[10px] text-slate-500 dark:text-slate-400 tracking-[0.1em] uppercase mb-1 font-medium">{label}</div>
      <div className="font-outfit text-3xl font-bold leading-none tracking-tight" style={{ color }}>{value}</div>
      {sub && <div className="text-xs text-slate-500 dark:text-slate-400 mt-2 font-medium">{sub}</div>}
    </div>
  )
}

