import { useState, useEffect } from 'react'
import { MapContainer, TileLayer, CircleMarker, Popup, Tooltip } from 'react-leaflet'
// @ts-ignore
import 'leaflet/dist/leaflet.css'
import { liveIncidents, citizenReports, statsSummary } from '../data/jakartaData'
import StatCard from '../components/StatCard'

const severityColor: Record<string, string> = { critical: '#EF4444', high: '#F97316', medium: '#F59E0B', low: '#22C55E' }
const severityLabel: Record<string, string> = { critical: 'KRITIS', high: 'TINGGI', medium: 'SEDANG', low: 'RENDAH' }
const statusColor: Record<string, string> = { verified: '#22C55E', processing: '#F59E0B', rejected: '#EF4444' }
const statusLabel: Record<string, string> = { verified: '✓ Terverifikasi', processing: '⟳ Diproses', rejected: '✗ Ditolak' }

export default function ConnectPage() {
  const [tab, setTab] = useState('incidents')
  const [incidents] = useState(liveIncidents)
  const [reports, setReports] = useState(citizenReports)
  const [form, setForm] = useState({ jenis: '', lokasi: '', deskripsi: '', channel: 'JAKI' })
  const [submitted, setSubmitted] = useState(false)
  const [newAlert, setNewAlert] = useState<any>(null)

  // Simulate incoming alert every 15s
  useEffect(() => {
    const timer = setInterval(() => {
      const alerts = [
        'Perlambatan arus terdeteksi di Jl. Pramuka arah Matraman',
        'Kendaraan parkir liar terdeteksi di depan Stasiun Kota',
        'Kemacetan terpantau di Jl. MT Haryono arah Cawang',
      ]
      setNewAlert(alerts[Math.floor(Math.random() * alerts.length)])
      setTimeout(() => setNewAlert(null), 4000)
    }, 15000)
    return () => clearInterval(timer)
  }, [])

  const handleSubmit = () => {
    if (!form.jenis || !form.lokasi) return
    const newReport = {
      id: `r0${reports.length + 1}`,
      lat: -6.2 + (Math.random() - 0.5) * 0.15,
      lng: 106.83 + (Math.random() - 0.5) * 0.15,
      status: 'processing', confidence: Math.floor(Math.random() * 40 + 50),
      location: form.lokasi, type: form.jenis, channel: form.channel,
      reportedAt: new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }),
      reporterCode: `WRG-${Math.floor(Math.random() * 9000 + 1000)}`,
      description: form.deskripsi || '(tidak ada deskripsi)',
      action: 'Laporan diterima, validasi CCTV sedang berjalan...',
    }
    setReports(prev => [newReport, ...prev])
    setSubmitted(true)
    setForm({ jenis: '', lokasi: '', deskripsi: '', channel: 'JAKI' })
    setTimeout(() => setSubmitted(false), 4000)
  }

  return (
    <div style={{ minHeight: '100vh', background: '#080D1A', fontFamily: "'DM Sans', sans-serif" }}>

      {/* BMKG-style top alert banner */}
      {newAlert && (
        <div style={{
          background: 'linear-gradient(90deg, #0B6E5F, #1540C8)',
          padding: '10px 28px', display: 'flex', alignItems: 'center', gap: 12,
          animation: 'slideDown 0.3s ease',
        }}>
          <span style={{ fontSize: 16 }}>🔔</span>
          <span style={{ fontFamily: "'DM Mono', monospace", fontSize: 12, color: '#fff' }}>
            ALERT OTOMATIS AI: {newAlert}
          </span>
          <span style={{ marginLeft: 'auto', fontFamily: "'DM Mono', monospace", fontSize: 10, color: 'rgba(255,255,255,0.6)' }}>
            Dikirim ke warga sekitar via JAKI
          </span>
        </div>
      )}

      <div style={{ padding: '20px 28px 0', maxWidth: 1280, margin: '0 auto' }}>
        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <div style={{ width: 4, height: 28, background: '#2EC4A0', borderRadius: 2 }} />
            <div>
              <h1 style={{ fontFamily: "'Syne', sans-serif", fontWeight: 800, fontSize: 22, color: '#E8EDF8', margin: 0 }}>
                JAGALANTAS <span style={{ color: '#2EC4A0' }}>CONNECT</span>
              </h1>
              <p style={{ margin: 0, fontSize: 12, color: '#4A5580', fontFamily: "'DM Mono', monospace" }}>
                Bidirectional Citizen-AI Alert System · IndoBERT + BMKG-style Alerts
              </p>
            </div>
          </div>

          {/* Bidir badges */}
          <div style={{ display: 'flex', gap: 8 }}>
            <div style={{ background: '#0B6E5F22', border: '1px solid #0B6E5F66', borderRadius: 8, padding: '5px 12px', fontSize: 11, color: '#2EC4A0', fontFamily: "'DM Mono', monospace" }}>
              ⬆ Warga → Sistem
            </div>
            <div style={{ background: '#1540C822', border: '1px solid #1540C866', borderRadius: 8, padding: '5px 12px', fontSize: 11, color: '#4A7CF8', fontFamily: "'DM Mono', monospace" }}>
              ⬇ AI → Warga
            </div>
          </div>
        </div>

        {/* Stats */}
        <div style={{ display: 'flex', gap: 12, marginBottom: 20, flexWrap: 'wrap' }}>
          <StatCard icon="🚨" label="Insiden Aktif" value={statsSummary.activeIncidents} sub="Terdeteksi AI dari CCTV" color="#EF4444" glow />
          <StatCard icon="📱" label="Laporan Hari Ini" value={statsSummary.citizenReportsToday} sub="Dari warga via JAKI/CRM/WA" color="#2EC4A0" />
          <StatCard icon="✅" label="Terverifikasi" value={statsSummary.reportsVerified} sub={`${Math.round(statsSummary.reportsVerified/statsSummary.citizenReportsToday*100)}% confidence rate`} color="#22C55E" />
          <StatCard icon="🔔" label="Alert Terkirim" value="3.2K" sub="Warga diberitahu hari ini" color="#4A7CF8" />
        </div>
      </div>

      {/* Main: map + panel */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 400px', gap: 16, padding: '0 28px 28px', maxWidth: 1280, margin: '0 auto' }}>

        {/* Map */}
        <div style={{ border: '1px solid #1E2A45', borderRadius: 16, overflow: 'hidden' }}>
          <div style={{ background: '#0D1526', padding: '10px 14px', borderBottom: '1px solid #1E2A45', display: 'flex', gap: 6 }}>
            {[
              { id: 'incidents', label: '🚨 Insiden Aktif' },
              { id: 'reports', label: '📍 Laporan Warga' },
            ].map(t => (
              <button key={t.id} onClick={() => setTab(t.id)} style={{
                padding: '5px 14px', borderRadius: 6, border: 'none', cursor: 'pointer',
                fontFamily: "'DM Mono', monospace", fontSize: 11,
                background: tab === t.id ? '#2EC4A022' : 'transparent',
                color: tab === t.id ? '#2EC4A0' : '#4A5580',
                borderBottom: tab === t.id ? '2px solid #2EC4A0' : '2px solid transparent',
              }}>{t.label}</button>
            ))}
          </div>

          <MapContainer center={[-6.2088, 106.8456]} zoom={12} style={{ height: 460, width: '100%' }}>
            <TileLayer attribution='&copy; OpenStreetMap' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

            {tab === 'incidents' && incidents.map(inc => (
              <CircleMarker
                key={inc.id}
                center={[inc.lat, inc.lng]}
                radius={inc.severity === 'critical' ? 16 : inc.severity === 'high' ? 12 : 9}
                pathOptions={{
                  color: severityColor[inc.severity],
                  fillColor: severityColor[inc.severity],
                  fillOpacity: 0.4, weight: 2,
                }}
              >
                <Tooltip direction="top" permanent={inc.severity === 'critical'}>
                  <span style={{ fontFamily: 'monospace', fontSize: 10 }}>
                    {inc.type} · {inc.detectedAt}
                  </span>
                </Tooltip>
                <Popup>
                  <div style={{ fontFamily: 'sans-serif', minWidth: 200 }}>
                    <b style={{ color: severityColor[inc.severity] }}>{inc.type}</b><br />
                    <span style={{ fontSize: 12 }}>{inc.location}</span><br />
                    <span style={{ fontSize: 11, color: '#666' }}>{inc.description}</span><br />
                    <span style={{ fontSize: 11 }}>Sumber: {inc.source}</span><br />
                    {inc.alertSent && <span style={{ fontSize: 11, color: 'green' }}>✓ Alert terkirim ke {inc.recipients} warga</span>}
                  </div>
                </Popup>
              </CircleMarker>
            ))}

            {tab === 'reports' && reports.map(rep => (
              <CircleMarker
                key={rep.id}
                center={[rep.lat, rep.lng]}
                radius={9}
                pathOptions={{
                  color: statusColor[rep.status],
                  fillColor: statusColor[rep.status],
                  fillOpacity: 0.5, weight: 2,
                }}
              >
                <Tooltip direction="top">
                  <span style={{ fontFamily: 'monospace', fontSize: 10 }}>
                    {rep.type} · {statusLabel[rep.status]}
                  </span>
                </Tooltip>
                <Popup>
                  <div style={{ fontFamily: 'sans-serif', minWidth: 200 }}>
                    <b>{rep.type}</b> — <span style={{ color: statusColor[rep.status] }}>{statusLabel[rep.status]}</span><br />
                    <span style={{ fontSize: 12 }}>{rep.location}</span><br />
                    <span style={{ fontSize: 11, color: '#666' }}>{rep.description}</span><br />
                    <span style={{ fontSize: 11 }}>Confidence: {rep.confidence}%</span><br />
                    <span style={{ fontSize: 11, color: '#666' }}>Channel: {rep.channel} · {rep.reportedAt}</span>
                  </div>
                </Popup>
              </CircleMarker>
            ))}
          </MapContainer>

          <div style={{ background: '#0D1526', padding: '8px 14px', display: 'flex', gap: 14, borderTop: '1px solid #1E2A45', flexWrap: 'wrap' }}>
            {tab === 'incidents'
              ? Object.entries(severityColor).map(([k, v]) => <LegendDot key={k} color={v} label={severityLabel[k]} />)
              : Object.entries(statusColor).map(([k, v]) => <LegendDot key={k} color={v} label={statusLabel[k]} />)
            }
          </div>
        </div>

        {/* Right panel */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>

          {/* Incident feed */}
          <div style={{ background: '#0D1526', border: '1px solid #1E2A45', borderRadius: 16, padding: 16 }}>
            <div style={{ fontFamily: "'DM Mono', monospace", fontSize: 10, color: '#4A5580', letterSpacing: '0.1em', marginBottom: 12 }}>
              ⬇ ALERT FEED — AI DETEKSI INSIDEN
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8, maxHeight: 240, overflowY: 'auto' }}>
              {incidents.map(inc => (
                <div key={inc.id} style={{
                  padding: '10px 12px', background: '#080D1A', borderRadius: 8,
                  borderLeft: `3px solid ${severityColor[inc.severity]}`,
                }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                    <span style={{ fontSize: 12, fontWeight: 600, color: '#E8EDF8' }}>{inc.type}</span>
                    <span style={{
                      fontFamily: "'DM Mono', monospace", fontSize: 9, padding: '2px 7px',
                      borderRadius: 99, background: `${severityColor[inc.severity]}22`,
                      color: severityColor[inc.severity],
                    }}>{severityLabel[inc.severity]}</span>
                  </div>
                  <div style={{ fontSize: 11, color: '#6B7A9E', marginTop: 3 }}>{inc.location}</div>
                  <div style={{ fontSize: 11, color: '#4A5580', marginTop: 2 }}>{inc.description}</div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 5 }}>
                    <span style={{ fontFamily: "'DM Mono', monospace", fontSize: 9, color: '#4A5580' }}>
                      {inc.source} · {inc.detectedAt} WIB
                    </span>
                    {inc.alertSent && (
                      <span style={{ fontFamily: "'DM Mono', monospace", fontSize: 9, color: '#2EC4A0' }}>
                        🔔 {inc.recipients} warga
                      </span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Citizen report form */}
          <div style={{ background: '#0D1526', border: '1px solid #1E2A45', borderRadius: 16, padding: 16 }}>
            <div style={{ fontFamily: "'DM Mono', monospace", fontSize: 10, color: '#4A5580', letterSpacing: '0.1em', marginBottom: 12 }}>
              ⬆ LAPORAN WARGA — SIMULASI JAKI
            </div>

            {submitted ? (
              <div style={{ padding: 16, background: '#0B6E5F22', border: '1px solid #0B6E5F55', borderRadius: 10, textAlign: 'center' }}>
                <div style={{ fontSize: 24, marginBottom: 6 }}>✅</div>
                <div style={{ fontSize: 13, color: '#2EC4A0', fontWeight: 600 }}>Laporan Diterima!</div>
                <div style={{ fontSize: 11, color: '#4A5580', marginTop: 4 }}>Validasi CCTV sedang berjalan...</div>
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                <select
                  value={form.jenis}
                  onChange={e => setForm(f => ({ ...f, jenis: e.target.value }))}
                  style={inputStyle}
                >
                  <option value="">Jenis pelanggaran/insiden *</option>
                  <option>Parkir Liar</option>
                  <option>Kendaraan di Jalur Busway</option>
                  <option>Kendaraan di Jalur Sepeda</option>
                  <option>Kecelakaan</option>
                  <option>Kemacetan Parah</option>
                  <option>Lainnya</option>
                </select>
                <input
                  placeholder="Lokasi kejadian *"
                  value={form.lokasi}
                  onChange={e => setForm(f => ({ ...f, lokasi: e.target.value }))}
                  style={inputStyle}
                />
                <textarea
                  placeholder="Deskripsi (opsional)"
                  value={form.deskripsi}
                  onChange={e => setForm(f => ({ ...f, deskripsi: e.target.value }))}
                  style={{ ...inputStyle, height: 70, resize: 'none' }}
                />
                <div style={{ display: 'flex', gap: 6 }}>
                  {['JAKI', 'WhatsApp', 'CRM'].map(ch => (
                    <button key={ch} onClick={() => setForm(f => ({ ...f, channel: ch }))} style={{
                      flex: 1, padding: '6px 0', borderRadius: 6, border: '1px solid',
                      borderColor: form.channel === ch ? '#2EC4A0' : '#1E2A45',
                      background: form.channel === ch ? '#0B6E5F22' : 'transparent',
                      color: form.channel === ch ? '#2EC4A0' : '#4A5580',
                      cursor: 'pointer', fontFamily: "'DM Mono', monospace", fontSize: 10,
                    }}>{ch}</button>
                  ))}
                </div>
                <button onClick={handleSubmit} style={{
                  padding: '10px', borderRadius: 8, border: 'none', cursor: 'pointer',
                  background: form.jenis && form.lokasi ? 'linear-gradient(90deg, #0B6E5F, #1540C8)' : '#1E2A45',
                  color: form.jenis && form.lokasi ? '#fff' : '#4A5580',
                  fontFamily: "'Syne', sans-serif", fontWeight: 700, fontSize: 13,
                  transition: 'all 0.2s',
                }}>
                  Kirim Laporan
                </button>
              </div>
            )}
          </div>

          {/* Recent reports */}
          <div style={{ background: '#0D1526', border: '1px solid #1E2A45', borderRadius: 16, padding: 16 }}>
            <div style={{ fontFamily: "'DM Mono', monospace", fontSize: 10, color: '#4A5580', letterSpacing: '0.1em', marginBottom: 10 }}>
              📋 LAPORAN TERBARU
            </div>
            {reports.slice(0, 3).map(rep => (
              <div key={rep.id} style={{ marginBottom: 8, padding: '8px 10px', background: '#080D1A', borderRadius: 8, borderLeft: `3px solid ${statusColor[rep.status]}` }}>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span style={{ fontSize: 11, fontWeight: 600, color: '#E8EDF8' }}>{rep.type}</span>
                  <span style={{ fontFamily: "'DM Mono', monospace", fontSize: 9, color: statusColor[rep.status] }}>
                    {statusLabel[rep.status]}
                  </span>
                </div>
                <div style={{ fontSize: 10, color: '#4A5580', marginTop: 2 }}>{rep.location} · {rep.channel} · {rep.reportedAt}</div>
                <div style={{ fontSize: 10, color: '#6B7A9E', marginTop: 2 }}>{rep.action}</div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <style>{`@keyframes slideDown { from { transform: translateY(-100%); opacity: 0; } to { transform: translateY(0); opacity: 1; } }`}</style>
    </div>
  )
}

const inputStyle = {
  width: '100%', padding: '9px 12px', borderRadius: 8,
  border: '1px solid #1E2A45', background: '#080D1A',
  color: '#C8D0E8', fontSize: 12, fontFamily: "'DM Sans', sans-serif",
  outline: 'none',
}

function LegendDot({ color, label }: any) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
      <div style={{ width: 8, height: 8, borderRadius: '50%', background: color }} />
      <span style={{ fontFamily: "'DM Mono', monospace", fontSize: 9, color: '#4A5580' }}>{label}</span>
    </div>
  )
}
